const lessons={brush:['DRAG TO PAINT','M44 24 L46 61'],liner:['DRAG TO DRAW','M41 25 C66 37 31 49 54 65'],dot:['TAP TO DOT','M42 32L53 57'],fan:['SWEEP TO BLEND','M32 48 Q50 36 65 48'],pick:['PLACE + MOVE','M15 65 Q20 10 50 44'],erase:['DRAG TO ERASE','M40 22L53 65'],stamp:['PRESS TO TRANSFER','M50 15L50 43'],extend:['PULL TO SHAPE','M50 57L50 78'],nail:['SHAPE + EXTEND','M50 57L50 78'],crystals:['PLACE + MOVE','M15 65 Q20 10 50 44'],stickers:['PLACE + SCALE','M15 15Q45 10 50 44'],metal:['PLACE + ARRANGE','M20 20L37 47']};
export function createToolPreviews(root){const panel=document.createElement('div');panel.id='tool-preview';panel.hidden=true;panel.setAttribute('role','status');root.append(panel);let timer,touchUntil=0;
 function hide(){clearTimeout(timer);panel.hidden=true;panel.replaceChildren();}
 function show(tool,temporary=false){if(root.classList.contains('presenting'))return;clearTimeout(timer);const [label,path]=lessons[tool]||lessons.brush;panel.dataset.lesson=tool;const nailPath=tool==='nail'?'M29 30Q29 14 50 14Q71 14 71 30L69 46Q67 59 50 59Q32 59 31 46Z':'M29 35 Q29 14 50 14 Q71 14 71 35 L69 61 Q67 77 50 77 Q32 76 31 61Z';panel.innerHTML=`<svg viewBox="0 0 110 94" aria-hidden="true"><defs><clipPath id="lesson-nail"><path d="${nailPath}"/></clipPath><mask id="lesson-erase"><rect width="110" height="94" fill="white"/><path class="demo-erase" d="M40 22L53 65" fill="none" stroke="black" stroke-width="17" stroke-linecap="round" pathLength="1"/></mask></defs><path d="${nailPath}" fill="#efded4" stroke="#a48a74" stroke-width="1"/><g clip-path="url(#lesson-nail)"><path class="demo-paint" d="${path}" fill="none" stroke="#b85649" stroke-width="${tool==='liner'?1.8:tool==='fan'?26:14}" stroke-linecap="round" pathLength="1"/><g class="demo-dots" fill="#b85649"><circle cx="42" cy="32" r="5"/><circle cx="53" cy="57" r="5"/></g><path class="demo-clean-base" d="M29 19H72V77H29Z" fill="#b85649" mask="url(#lesson-erase)"/></g><path class="demo-extension" d="${tool==='nail'?'M31 47Q50 54 69 47L53 86Q50 91 47 86Z':'M32 59Q50 69 69 59L53 87Q50 91 47 87Z'}" fill="#eee4d388" stroke="#a48a74" stroke-width=".8"/><g class="demo-tool"><path d="M0 -33V-6" stroke="#947765" stroke-width="4" stroke-linecap="round"/><path d="M0 -9V0" stroke="#b9c6b8" stroke-width="5"/><path d="M-2 0L0 5 2 0Z" fill="#987254"/></g><g class="demo-beads"><path d="M50 37 56 44 50 51 44 44Z" fill="#ded7e6" stroke="#8b7664" stroke-width=".7"/><circle cx="39" cy="40" r="2.3"/><circle cx="61" cy="40" r="2.3"/><circle cx="50" cy="56" r="2.3"/></g><path class="demo-sticker" d="M0 -8 2 -2 8 -2 3 2 5 8 0 4 -5 8 -3 2 -8 -2 -2 -2Z" fill="#5e5348"/><path class="demo-gem" d="M0 -6 5 0 0 6 -5 0Z" fill="#d4d6e0" stroke="#8d807a" stroke-width=".7"/></svg><span>${label}</span>`;
 panel.style.setProperty('--gesture',`path('${path}')`);panel.hidden=false;if(temporary)timer=setTimeout(hide,1800);}
 root.querySelectorAll('[data-tool],[data-preview]').forEach(button=>{const tool=button.dataset.preview||button.dataset.tool;button.addEventListener('pointerenter',e=>{if(e.pointerType!=='touch')show(tool);});button.addEventListener('pointerleave',e=>{if(e.pointerType!=='touch')hide();});button.addEventListener('focus',()=>{if(Date.now()>touchUntil)show(tool);});button.addEventListener('blur',hide);button.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'){touchUntil=Date.now()+1900;if(button.getAttribute('aria-pressed')!=='true')show(tool,true);else hide();}});button.addEventListener('click',e=>{if(e.pointerType!=='touch')hide();});});return {hide};}
